const cases=[{id:'MT-2026-1048',machine:'CNC-04 · Mori Seiki',issue:'Rung bất thường trục chính',status:'critical',statusText:'Đang điều tra',owner:'Nguyễn Minh',time:'08:42 hôm nay',kind:'Bất thường'},{id:'MT-2026-1047',machine:'ALC-02 · Máy đúc nhôm',issue:'Kiểm tra nhiệt độ dầu thủy lực',status:'done',statusText:'Hoàn tất',owner:'Phạm Đức Long',time:'07:15 hôm nay',kind:'Định kỳ'},{id:'MT-2026-1044',machine:'WASH-01 · Máy rửa',issue:'Áp suất bơm thấp',status:'review',statusText:'Chờ xác nhận',owner:'Vũ Thanh Tùng',time:'Hôm qua, 15:30',kind:'Bất thường'},{id:'MT-2026-1041',machine:'PRESS-06 · Máy ép',issue:'Bảo dưỡng bộ dẫn hướng',status:'done',statusText:'Hoàn tất',owner:'Nguyễn Minh',time:'Hôm qua, 13:10',kind:'Định kỳ'},{id:'MT-2026-1038',machine:'WELD-03 · Máy hàn',issue:'Dòng hàn không ổn định',status:'open',statusText:'Đã gọi chuyên gia',owner:'Trần Văn Hải',time:'02/10/2026, 10:24',kind:'Bất thường'}];
const knowledge=[{id:'KN-024',title:'Rung trục chính sau khi thay dao',machine:'CNC · Trục chính',author:'Trần Văn Hải',type:'Tri thức chuyên gia',date:'26/09/2026',state:'Đã duyệt',text:'Khi rung xuất hiện ngay sau thay dao, cần kiểm tra độ sạch bề mặt côn và lực kẹp trước khi kết luận bạc đạn. So sánh rung ở cùng tốc độ quay.'},{id:'CS-112',title:'Rung bất thường CNC-02 khi chạy tốc độ cao',machine:'CNC · Trục chính',author:'Lê Hoàng Nam',type:'Case sửa chữa',date:'18/09/2026',state:'Đã duyệt',text:'Rung tăng theo tốc độ. Phát hiện phoi bám trên mặt côn holder; vệ sinh và kiểm tra lại độ đảo trước khi chạy xác nhận.'},{id:'KN-019',title:'Phân biệt rung cơ khí và rung do gá đặt',machine:'CNC · Đồ gá',author:'Trần Văn Hải',type:'Tri thức chuyên gia',date:'12/09/2026',state:'Đã duyệt',text:'Nếu rung chỉ xuất hiện với một mã sản phẩm, kiểm tra bề mặt gá và độ kẹp trước khi can thiệp cụm trục.'},{id:'CS-098',title:'Áp suất bơm rửa giảm sau vệ sinh lọc',machine:'Máy rửa · Bơm tuần hoàn',author:'Phạm Đức Long',type:'Case sửa chữa',date:'09/09/2026',state:'Đã duyệt',text:'Sau vệ sinh lọc, áp suất thấp do gioăng lắp lệch. Kiểm tra rò rỉ và chiều lắp trước khi thay bơm.'}];
