const app=document.getElementById('app');
function nav(){return navItems.filter(([id,,,r])=>(r==='all'||r===state.role)&&rolePages[state.role].includes(id)).map(([id,label,ico])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon(ico)}</span><span>${label}</span>${id==='approvals'?'<span class="nav-count">3</span>':''}</button>`).join('')}
function shell(content){let role=roleData[state.role];let mobileItems=state.role==='maintenance'?[['dashboard','Tổng quan','grid'],['cases','Ca bảo trì','wrench'],['knowledge','Tra cứu','search']]:state.role==='expert'?[['dashboard','Tổng quan','grid'],['submit','Chia sẻ','book'],['capture','Cuộc họp','file'],['knowledge','Tra cứu','search']]:[['dashboard','Tổng quan','grid'],['approvals','Duyệt','check'],['knowledge','Kho tri thức','search']];return `<div class="app-shell"><aside class="sidebar"><div class="brand"><div class="brand-mark">D</div><div><div class="brand-name">DENSO</div><div class="brand-sub">Maintenance Hub</div></div></div><div class="workspace-label">Không gian làm việc</div><nav class="nav-list" aria-label="Điều hướng chính">${nav()}</nav><div class="sidebar-bottom"><div class="sidebar-note"><div class="sidebar-note-title">Kho tri thức đang hoạt động</div><p>248 bản ghi đã được chuyên gia xác nhận và sẵn sàng tra cứu.</p><button class="nav-item" data-page="knowledge" style="height:38px;padding:0;color:#8ecafa">Mở kho tri thức ${icon('arrow')}</button></div><div class="system-status"><span class="dot"></span> Hệ thống ổn định</div></div></aside><main class="main-column"><header class="topbar"><div class="crumb"><span class="crumb-parent">Không gian bảo trì　/　</span><strong>${pageNames[state.page]||'Tổng quan'}</strong></div><div class="top-actions"><button class="icon-button" aria-label="Thông báo" data-action="notifications">${icon('bell')}<i class="notify-dot"></i></button><div class="profile"><div class="avatar">${role.initials}</div><div class="profile-copy"><div class="profile-name">${role.name}</div><div class="profile-role">${role.label}</div></div></div><button class="btn btn-sm logout-button" data-action="logout" aria-label="Đăng xuất">Thoát</button></div></header><section class="content">${content}</section></main><nav class="phone-tabs" aria-label="Điều hướng nhanh">${mobileItems.map(([id,l,i])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon(i)}</span><span>${l}</span></button>`).join('')}</nav></div>`}
function heading(kicker,title,sub,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${sub}</p></div>${actions?`<div class="heading-actions">${actions}</div>`:''}</div>`}
function btn(label,action,kind='btn',ico=''){return `<button class="${kind}" data-action="${action}">${ico?icon(ico):''}${label}</button>`}
function stat(label,value,foot,ico){return `<article class="card stat-card"><div class="stat-top"><div class="stat-label">${label}</div><div class="stat-icon">${icon(ico)}</div></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div></article>`}
function tableRows(arr=cases){return arr.map(c=>`<tr data-case="${c.id}" class="open-case"><td><span class="machine-name">${c.id}</span><div class="secondary-line">${c.time}</div></td><td><span class="machine-name">${c.machine}</span><div class="secondary-line">${c.issue}</div></td><td><span class="status status-${c.status}">${c.statusText}</span></td><td>${c.owner}</td><td>${c.kind}</td><td>${icon('chevron')}</td></tr>`).join('')}
function dashboard(){if(state.role==='lead')return `${heading('KHU VỰC KIỂM DUYỆT','Xin chào, Anh Lê Quốc Anh','Quản lý chất lượng tri thức và phản hồi cho người đóng góp.',btn('Mở hàng chờ duyệt','gotoApprovals','btn btn-primary','check'))}<div class="grid stats-grid">${stat('Đang chờ kiểm duyệt','03','2 tri thức · 1 case','clock')}${stat('Cần tác giả bổ sung','01','Đã gửi phản hồi','edit')}${stat('Tri thức đã xác nhận','248','+6 trong tháng này','book')}${stat('Duyệt trong tháng','17','Thời gian phản hồi TB 1,4 ngày','chart')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><div class="card-title">Nội dung chờ bạn xem</div><div class="card-subtitle">Tác giả và nguồn nội dung được lưu xuyên suốt quy trình</div></div><button class="link-button" data-page="approvals">Mở hàng chờ →</button></div>${pending.slice(0,3).map(p=>`<div class="review-row"><div class="review-avatar">${p.initials}</div><div class="review-main"><div class="review-title">${p.title}</div><div class="review-meta">${p.id} · ${p.author} · ${p.date}</div></div><span class="status status-review">Chờ duyệt</span></div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="card-title">Nguyên tắc duyệt</div><div class="card-subtitle">Tri thức đáng tin, có tác giả và giới hạn áp dụng rõ</div></div></div><div class="activity-list"><div class="activity-item"><div class="activity-marker">${icon('users')}</div><div class="activity-copy">Giữ riêng <strong>tác giả tri thức</strong> và <strong>người phê duyệt</strong>.</div></div><div class="activity-item"><div class="activity-marker">${icon('edit')}</div><div class="activity-copy">Thay đổi ý nghĩa chuyên môn cần <strong>tác giả xác nhận</strong>.</div></div><div class="activity-item"><div class="activity-marker">${icon('shield')}</div><div class="activity-copy">Nội dung chưa duyệt <strong>không dùng làm gợi ý xử lý</strong>.</div></div></div></section></div>`;if(state.role==='expert')return `${heading('KHÔNG GIAN CHUYÊN GIA','Xin chào, Anh Trần Văn Hải','Chia sẻ kinh nghiệm khi thuận tiện và theo dõi cách đội ngũ tái sử dụng tri thức.',btn('Ghi nhanh kinh nghiệm','newKnowledge','btn btn-primary','plus'))}<div class="grid stats-grid">${stat('Tri thức của tôi','18','14 đã duyệt · 2 chờ duyệt','book')}${stat('Đề xuất cần bổ sung','01','Phản hồi từ Chuyên gia trưởng','edit')}${stat('Case đã hỗ trợ','06','3 case trong tháng này','wrench')}${stat('Bản nháp đang lưu','02','Có thể tiếp tục bất kỳ lúc nào','save')}</div><div class="ai-banner"><div class="ai-symbol">${icon('file')}</div><div class="ai-banner-copy"><strong>Vừa kết thúc buổi trao đổi?</strong> Dán ghi chú hoặc biên bản để tạo đề xuất tri thức. Bạn sẽ rà soát nội dung trước khi gửi kiểm duyệt.</div>${btn('Thêm ghi chú họp','gotoCapture','btn btn-sm','arrow')}</div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><div class="card-title">Tri thức tôi đã chia sẻ</div><div class="card-subtitle">Theo dõi trạng thái và phản hồi của người duyệt</div></div><button class="link-button" data-page="submit">Tạo mới →</button></div>${knowledge.filter(k=>k.author==='Trần Văn Hải').slice(0,3).map(k=>`<div class="review-row"><div class="review-avatar">${roleData.expert.initials}</div><div class="review-main"><div class="review-title">${k.title}</div><div class="review-meta">${k.id} · ${k.date} · ${k.type}</div></div><span class="status status-done">${k.state}</span></div>`).join('')}</section><section class="card"><div class="card-head"><div><div class="card-title">Hoạt động tri thức</div><div class="card-subtitle">Đóng góp và sử dụng gần đây</div></div></div><div class="activity-list"><div class="activity-item"><div class="activity-marker">${icon('checkcircle')}</div><div><div class="activity-copy"><strong>KN-024</strong> đã được phê duyệt</div><div class="activity-time">Hôm nay, 09:12 · Có thể tra cứu</div></div></div><div class="activity-item"><div class="activity-marker">${icon('file')}</div><div><div class="activity-copy">Một ghi chú họp có <strong>2 đề xuất tri thức</strong></div><div class="activity-time">01/10/2026 · Chờ chuyên gia xác nhận</div></div></div></div></section></div>`;return `${heading('THỨ HAI · 05 THÁNG 10, 2026','Chào buổi sáng, Nguyễn Minh','Theo dõi ca hiện trường và tra cứu kinh nghiệm đã được xác nhận.',btn('Tạo ca bảo trì','newCase','btn btn-primary','plus'))}<div class="grid stats-grid">${stat('Ca bảo trì hôm nay','12','8 hoàn tất · 4 đang mở','wrench')}${stat('Máy đang cần chú ý','03','1 ca cần chuyên gia','alert')}${stat('Tri thức đã xác nhận','248','+6 trong tháng này','book')}${stat('Thời gian phản hồi chuyên gia','18 phút','↓ 12% so với tháng trước','clock')}</div><div class="ai-banner"><div class="ai-symbol">${icon('spark')}</div><div class="ai-banner-copy"><strong>Trợ lý tri thức sẵn sàng.</strong> Tra cứu theo máy, mã lỗi hoặc mô tả dấu hiệu. AI sẽ đối chiếu với case và kinh nghiệm đã được duyệt, kèm nguồn tham khảo.</div>${btn('Tra cứu ngay','gotoKnowledge','btn btn-sm','arrow')}<span class="badge">Nguồn đã duyệt</span></div><div class="grid dashboard-grid"><section class="card"><div class="card-head"><div><div class="card-title">Ca bảo trì gần đây</div><div class="card-subtitle">Lịch sử công việc và tình trạng các ca đang xử lý</div></div><button class="link-button" data-page="cases">Xem tất cả →</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mã ca</th><th>Thiết bị / nội dung</th><th>Trạng thái</th><th>Phụ trách</th><th>Loại ca</th><th></th></tr></thead><tbody>${tableRows(cases.slice(0,4))}</tbody></table></div></section><section class="card"><div class="card-head"><div><div class="card-title">Hoạt động gần đây</div><div class="card-subtitle">Cập nhật từ nhóm bảo trì</div></div></div><div class="activity-list"><div class="activity-item"><div class="activity-marker">${icon('checkcircle')}</div><div><div class="activity-copy"><strong>KN-024</strong> đã được Chuyên gia trưởng phê duyệt</div><div class="activity-time">Hôm nay, 09:12 · Tri thức chuyên gia</div></div></div><div class="activity-item"><div class="activity-marker">${icon('wrench')}</div><div><div class="activity-copy"><strong>MT-2026-1048</strong> tạo mới · rung trục chính CNC-04</div><div class="activity-time">Hôm nay, 08:42 · Nguyễn Minh</div></div></div><div class="activity-item"><div class="activity-marker">${icon('users')}</div><div><div class="activity-copy">Chuyên gia được gọi hỗ trợ <strong>WELD-03</strong></div><div class="activity-time">02/10/2026, 10:24 · Trần Văn Hải</div></div></div><div class="activity-item"><div class="activity-marker">${icon('book')}</div><div><div class="activity-copy">Ghi chú cuộc họp tạo <strong>2 đề xuất tri thức</strong></div><div class="activity-time">01/10/2026, 16:05 · Đang chờ xác nhận</div></div></div></div></section></div>`}
function casesPage(){let maintenanceUser=state.role==='maintenance';return `${heading(maintenanceUser?'NHẬT KÝ CÔNG VIỆC':'CA CÓ LIÊN QUAN','Ca bảo trì',maintenanceUser?'Mỗi lần làm việc được lưu vào lịch sử máy. Case có giá trị tái sử dụng sẽ được đề xuất đưa vào kho tri thức.':'Tra cứu các ca liên quan đến thiết bị và kinh nghiệm chuyên môn của bạn.',maintenanceUser?btn('Tạo ca mới','newCase','btn btn-primary','plus'):'')}<div class="filter-bar"><label class="search-box">${icon('search')}<input id="caseSearch" placeholder="Tìm mã ca, máy hoặc dấu hiệu..." value="${state.search}"></label><select class="filter-select"><option>Tất cả loại ca</option><option>Bất thường</option><option>Định kỳ</option></select><select class="filter-select"><option>Mọi trạng thái</option><option>Đang điều tra</option><option>Chờ xác nhận</option><option>Hoàn tất</option></select><button class="btn">${icon('filter')} Bộ lọc</button></div><div class="card"><div class="card-head"><div><div class="card-title">${cases.length} ca gần đây</div><div class="card-subtitle">Dữ liệu demo · ${maintenanceUser?'Lịch sử sửa chữa không phụ thuộc phê duyệt tri thức':'Chỉ người bảo trì phụ trách ca mới tạo và hoàn tất báo cáo'}</div></div><span class="pill">Cập nhật vừa xong</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Mã ca / thời gian</th><th>Thiết bị / nội dung</th><th>Trạng thái</th><th>Phụ trách</th><th>Loại ca</th><th></th></tr></thead><tbody id="casesBody">${tableRows(cases)}</tbody></table></div></div>`}
function resultCard(k,score,tags=[],diff=[]){return `<article class="knowledge-result"><div class="result-top"><div><div class="result-title">${k.title}</div><div class="result-meta">${k.id} · ${k.type} · ${k.author} · ${k.date}</div></div><div class="relevance">${score} liên quan</div></div><div class="result-body">${k.text}</div><div class="match-tags">${tags.map(t=>`<span class="match-tag">✓ ${t}</span>`).join('')}${diff.map(t=>`<span class="match-tag mismatch">! ${t}</span>`).join('')}</div></article>`}
function knowledgePage(){let filtered=knowledge.filter(k=>(k.title+k.machine+k.text+k.id).toLowerCase().includes(state.search.toLowerCase()));return `${heading('KHO TRI THỨC DENSO','Tra cứu kinh nghiệm bảo trì','Tìm trong case sửa chữa và tri thức chuyên gia đã được duyệt; kiểm tra điểm tương đồng trước khi áp dụng.',`<span class="pill">248 nội dung đã duyệt</span>`)}<div class="card" style="padding:17px;margin-bottom:15px"><div class="filter-bar" style="margin:0"><label class="search-box">${icon('search')}<input id="knowledgeSearch" placeholder="Ví dụ: CNC rung trục chính sau khi thay dao..." value="${state.search}"></label><select class="filter-select"><option>Tất cả thiết bị</option><option>CNC</option><option>Máy đúc nhôm</option><option>Máy rửa</option></select><button class="btn btn-primary" data-action="searchKnowledge">${icon('search')} Tìm kiếm</button></div><div style="font-size:9px;color:#8998a4;margin:10px 0 0 2px">AI tìm kiếm trên các nguồn đã duyệt · Mọi gợi ý đều liên kết về bản ghi gốc</div></div><div class="tabs" style="margin-bottom:13px"><button class="tab active">Tất cả nguồn <span class="pill">${filtered.length}</span></button><button class="tab">Case sửa chữa</button><button class="tab">Tri thức chuyên gia</button></div><div id="knowledgeResults">${filtered.length?filtered.map((k,i)=>resultCard(k,['Rất phù hợp','Phù hợp','Có liên quan','Tham khảo'][Math.min(i,3)],i===0?['Cùng cụm trục chính','Triệu chứng rung','Sau thay dao']:['Cùng nhóm máy','Bước kiểm tra hữu ích'],i===0?['Cần xác nhận tốc độ vận hành']:[])).join(''):'<div class="card empty-state"><strong>Chưa tìm thấy nội dung phù hợp</strong>Thử tìm theo mã máy, bộ phận hoặc dấu hiệu khác.</div>'}</div>`}
function submitPage(){return `${heading('CHIA SẺ KINH NGHIỆM','Ghi nhận tri thức chuyên gia','Lưu lại dấu hiệu, cách suy luận và giới hạn áp dụng để đồng nghiệp có thể tham khảo.',`<span class="pill">Tác giả: ${roleData[state.role].name}</span>`)}<div class="mode-card card" style="margin-bottom:14px"><div class="card-head" style="padding:0 0 13px"><div><div class="card-title">Bắt đầu theo cách thuận tiện</div><div class="card-subtitle">Có thể chuyển giữa ghi nhanh và biểu mẫu bất kỳ lúc nào</div></div></div><div class="mode-grid"><button class="mode-option ${state.knowledgeMode==='quick'?'selected':''}" data-mode="quick"><div class="mode-option-title">${icon('edit')}　Ghi nhanh bằng nội dung tự do</div><p>Ghi chú, gạch đầu dòng hoặc nội dung đã có. AI sẽ đề xuất sắp xếp vào biểu mẫu.</p><small>PHÙ HỢP KHI ĐANG BẬN</small></button><button class="mode-option ${state.knowledgeMode==='form'?'selected':''}" data-mode="form"><div class="mode-option-title">${icon('file')}　Điền biểu mẫu có cấu trúc</div><p>Nhập trực tiếp theo từng trường, kiểm tra rõ nội dung trước khi gửi duyệt.</p><small>KIỂM SOÁT ĐẦY ĐỦ HƠN</small></button></div></div>${state.knowledgeMode==='quick'?quickKnowledgeForm():structuredKnowledgeForm()}`}
function quickKnowledgeForm(){return `<div class="card form-card"><div class="form-section"><div class="form-section-title">Ghi lại điều bạn muốn chia sẻ</div><div class="form-help">Bản nháp được tự lưu. Không cần viết hoàn chỉnh trong một lần.</div><div class="field"><label for="quickText">Nội dung kinh nghiệm <span class="required">*</span></label><textarea id="quickText" placeholder="Ví dụ: Khi máy CNC phát tiếng rung sau khi thay dao, trước tiên tôi kiểm tra bề mặt côn holder vì phoi bám có thể tạo độ lệch. Nếu chỉ rung ở một mã sản phẩm thì cần xem lại đồ gá trước khi kiểm tra trục chính...">${localStorage.getItem('expertQuickDraft')||''}</textarea><span class="field-hint">Có thể ghi theo ý chính, dấu hiệu quan sát, điều đã thử, kết quả hoặc lưu ý cho người mới.</span></div></div><div class="form-section"><div class="form-grid"><div class="field"><label>Máy / nhóm máy liên quan</label><select><option>Chọn nếu phù hợp</option><option>CNC</option><option>Máy đúc nhôm</option><option>Máy rửa linh kiện</option><option>Máy ép</option><option>Máy hàn lắp ráp</option></select></div><div class="field"><label>Phạm vi chia sẻ</label><select><option>Nhóm bảo trì</option><option>Toàn nhà máy</option></select></div></div><div class="callout callout-info" style="margin-top:14px">AI sẽ hỗ trợ cấu trúc nội dung và chỉ ra thông tin còn thiếu. Bạn sẽ kiểm tra bản sắp xếp trước khi gửi duyệt; AI không tự bổ sung điều chưa được cung cấp.</div></div><div class="form-footer"><div class="autosave">${icon('save')} Tự lưu bản nháp trên thiết bị</div><div class="form-actions">${btn('Lưu nháp','saveKnowledge','btn')}${btn('Tiếp tục kiểm tra','structureKnowledge','btn btn-primary','arrow')}</div></div></div>`}
